INSERT INTO "messages" ("id", "folder_id", "message_id", "subject", "from_addr", "to_addr_json", "cc_addr_json", "bcc_addr_json", "date", "body_text", "body_html", "is_read", "is_important", "is_flagged", "in_reply_to", "references_header", "headers_json", "uid", "size", "created_at") VALUES (6, 2, '<bursar.fall2026.documents.0614@northlake.example>', 'Bursar documentation checklist', 'bursar@northlake.example', '["finance.owner@example.com"]', '[]', '[]', '2026-06-14T08:15:00Z', 'Before the Fall 2026 supported-cost review, the bursar needs the enrollment certification, published allowance, scholarship posting, lease dates, and itemized meal invoice. The review appointment remains scheduled for June 22.', NULL, 1, 1, 1, NULL, NULL, '{"thread_class":"bursar_checklist","academic_period":"Fall 2026","document_status":"open"}', 6005, 938, '2026-06-14T08:15:00Z');
